-- Enlaces carta <-> producto físico de Mitos y Leyendas, generados desde los data.json (campo productName).
-- Une por id y por nombre del producto: si algo no coincide en este entorno, esa fila se omite en vez de enlazar mal.
-- Es idempotente (ON CONFLICT DO NOTHING) y no modifica ninguna otra tabla.

CREATE TEMP TABLE _pp_expected (id INTEGER, name TEXT) ON COMMIT DROP;
